mapper.sql:
WHERE C.RQMT_DTTM >= #{stDttm}
  AND C.RQMT_DTTM < #{endDttm}

  AND C.LNK_ORG_ID = #{request.lnkOrgId}


  AND C.INFC_ID = #{request.infcId}



  AND C.HTTP_STAT_CD LIKE '2%'


  AND C.HTTP_STAT_CD NOT LIKE '2%'


  AND C.TRC_ID = TRIM(#{request.trcId})

mapper.select:
/* InterfaceCallMapper.selectInterfaceCallCount 조회 조건에 맞는 호출이력 건수를 조회 */
SELECT COUNT(*)
FROM TB_INFC_CALL_L C

/* InterfaceCallMapper.selectInterfaceCall 호출이력 1건을 요청·응답 본문까지 조회 */
SELECT ,
       C.RQMT_CONT,
       C.RSPN_CONT
FROM TB_INFC_CALL_L C
LEFT JOIN TB_LNK_ORG_M O ON O.LNK_ORG_ID = C.LNK_ORG_ID
LEFT JOIN TB_INFC_M I ON I.INFC_ID = C.INFC_ID
WHERE C.CALL_SN = #{callSn}
  AND C.RQMT_DTTM >= #{stDttm}
  AND C.RQMT_DTTM < #{endDttm}
